begin
 r:=public.home_planer_save_project(d);
 if r->>'schemaVersion'<>'8' or (r->>'revision')::int<>1 or jsonb_array_length(r->'fences'->0->'openings')<>2 or jsonb_array_length(r->'fences'->0->'posts')<>29 or jsonb_array_length(r->'fences'->0->'sections')<>27 then raise exception 'v8 fence roundtrip failed';end if;
 if r->'settings'->'site'->>'northAngle'<>'20' or r->'settings'->'site'->>'boundaryOffset'<>'1' then raise exception 'v8 site settings failed';end if;
 begin
  bad:=jsonb_set(r,'{fences,0,openings,0,width}','1000');
  perform public.home_planer_save_project(bad);raise exception 'out of segment gate accepted';
 exception when invalid_parameter_value then null;end;
 begin
  bad:=jsonb_set(r,'{settings,site,minPassage}','-1');
  perform public.home_planer_save_project(bad);raise exception 'negative clearance accepted';
 exception when invalid_parameter_value then null;end;
 begin
  bad:=jsonb_set(r,'{fences,0,posts,0,offset}','1000');
  perform public.home_planer_save_project(bad);raise exception 'out of segment post accepted';
 exception when invalid_parameter_value then null;end;
 begin
  bad:=(r - 'fences' - 'clearanceRules') || jsonb_build_object('schemaVersion',7,'layers',(select jsonb_agg(l) from jsonb_array_elements(r->'layers') l where l->>'id' not in ('fences','clearances')),'settings',(r->'settings') - 'site');
  perform public.home_planer_save_project(bad);raise exception 'v8 downgrade accepted';
 exception when sqlstate 'P0001' then
  get stacked diagnostics detail=PG_EXCEPTION_DETAIL;if detail is distinct from 'schema_conflict' then raise;end if;
 end;
 if not exists(select 1 from public.home_planer_projects where id='phase2-site-rollback-check' and revision=1 and document->>'schemaVersion'='8') then raise exception 'v8 state changed by rejected saves';end if;
